def solve(g):
    H=len(g);W=len(g[0]);out=[r[:] for r in g]
    for _ in range(4):
        for i in range(H):
            for j in range(W):
                if out[i][j]!=2: continue
                # check 4-orbit partners
                partners=[(H-1-i,j),(i,W-1-j),(H-1-i,W-1-j)]
                vals={g[y][x] for y,x in partners if g[y][x]!=2}
                if len(vals)==1:
                    out[i][j]=next(iter(vals)); continue
                cnt={}
                for dy in(-1,0,1):
                    for dx in(-1,0,1):
                        yy,xx=i+dy,j+dx
                        if 0<=yy<H and 0<=xx<W and g[yy][xx]!=2:
                            cnt[g[yy][xx]]=cnt.get(g[yy][xx],0)+1
                if cnt:
                    best=max(cnt.items(), key=lambda kv:(kv[1],-abs(ky-kv[0])))
                    v,c=best
                    out[i][j]=v
    return out
