def solve_consensus(g):
    n,m=len(g),len(g[0]); H,W=n,m
    out=[[g[r][c] for c in range(W)] for r in range(H)]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=2: continue
            cnt=Counter()
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    nr,nc=r+dr,c+dc
                    if 0<=nr<H and 0<=nc<W and g[nr][nc]!=2:
                        cnt[g[nr][nc]]+=1
            if cnt: out[r][c]=cnt.most_common(1)[0][0]
    return out
